            { "audit.footer", new[]{ "依据等级：本机实测指在这台机器上测量所得；台架实测指合成负载配对实验；机制明确指原理清楚但无量化数据；未验证指未经测量。", "Evidence levels: measured on this machine means measured on this very machine; bench-verified means paired experiments under synthetic load; mechanism-clear means the principle is understood but there is no quantitative data; unverified means not measured." } },
            { "v16.graphics.sub", new[]{ "显卡相关开关。逐游戏的项仅在游戏期间生效，退出后自动还原。", "GPU-related switches. Per-game items only take effect while the game runs and are restored automatically on exit." } },
            { "v16.env.sub", new[]{ "本页修改系统底层设置，均需重启生效，且不随 Pavise 卸载自动还原。需要恢复请先在此处关闭。", "This page modifies low-level system settings. All require a reboot, and none revert automatically when Pavise is uninstalled. To restore, turn them off here first." } },
            { "v17.log.sub", new[]{ "最近 220 行，切换至本页自动刷新。每局的时长、压制数量和成效同样记录于此。", "Last 220 lines; refreshes automatically when you switch to this page. Each match's duration, suppression count and results are recorded here too." } },
            { "sec.env.kernel", new[]{ "内核与驱动，需重启，改动不随 Pavise 卸载消失", "Kernel and drivers — reboot required; changes do not disappear when Pavise is uninstalled" } },
