            { "t.framediag.2", new[]{ "帧卡顿溯源 帧时钟会话起不来 本局未启用", "Stutter attribution: the frame clock session could not start; not enabled this session" } },
            { "t.framediag.3", new[]{ "帧卡顿溯源 中断会话起不来 本局未启用", "Stutter attribution: the interrupt session could not start; not enabled this session" } },
            { "t.framediag.4", new[]{ "帧卡顿溯源 自身开销超预算 已中途停止 以免自己成为卡顿源", "Stutter attribution stopped mid-session: its own overhead exceeded budget, so it would have become a stutter source itself" } },
            { "t.framediag.5", new[]{ "采样期间丢过事件 本局归因结论不可信 已丢弃", "Events were dropped while sampling, so this session's attribution is not trustworthy and was discarded" } },
