            { "t.systemaudithardware.1", new[]{ "内存频率", "Memory frequency" } },
            { "t.systemaudithardware.2", new[]{ " 标称 ", " rated " } },
            { "t.systemaudithardware.3", new[]{ "读取失败", "Read failed" } },
            { "t.systemaudithardware.4", new[]{ "疑似跑在 JEDEC 默认频率 没吃满内存条标称速度 去 BIOS 开 XMP 或 EXPO 台架实测 1% low 能高一成以上 板载内存机型不适用此判断", "Likely running at the JEDEC default frequency, not reaching your memory sticks' rated speed. Enable XMP or EXPO in BIOS; bench-verified 1% low gains of 10% or more. This check does not apply to machines with onboard memory." } },
            { "t.systemaudithardware.5", new[]{ "已接近标称频率 或本机读数不足以判断 不用处理", "Close to the rated frequency, or local readings are insufficient to judge. No action needed." } },
            { "t.systemaudithardware.6", new[]{ "内存通道", "Memory channels" } },
            { "t.systemaudithardware.7", new[]{ " 条内存", " memory module(s)" } },
            { "t.systemaudithardware.8", new[]{ "单条内存只有单通道带宽 1% low 受影响明显 加装一条同规格内存组双通道是性价比最高的升级之一 板载内存机型不适用", "A single memory module only gets single-channel bandwidth, which noticeably hurts 1% lows. Adding a matching module for dual-channel is one of the most cost-effective upgrades. Not applicable to machines with soldered memory." } },
            { "t.systemaudithardware.9", new[]{ "两条及以上 一般已组成双通道 不用处理", "Two or more modules, usually already running dual-channel. No action needed." } },
            { "t.systemaudithardware.10", new[]{ "多屏刷新率", "Multi-monitor refresh rates" } },
            { "t.systemaudithardware.11", new[]{ "多台显示器刷新率不一致 该版本系统的桌面合成器会因此掉帧 副屏播视频时主屏最明显 24H2 已改进 建议更新系统或把副屏设为相同刷新率", "Monitors are running at mismatched refresh rates. On this Windows version the desktop compositor drops frames because of it, most visibly on the primary display while the secondary plays video. 24H2 improved this; update Windows or set the secondary display to the same refresh rate." } },
            { "t.systemaudithardware.12", new[]{ "刷新率不一致 当前系统已含混合刷新率改进 一般无碍", "Refresh rates differ, but this Windows version includes the mixed-refresh-rate improvements. Generally fine." } },
            { "t.systemaudithardware.13", new[]{ "各屏一致 不用处理", "All displays match. No action needed." } },
            { "t.systemaudithardware.14", new[]{ "CPU 降频事件", "CPU throttling events" } },
            { "t.systemaudithardware.15", new[]{ "近 7 天 ", "Last 7 days " } },
            { "t.systemaudithardware.16", new[]{ "近 7 天无记录", "No records in the last 7 days" } },
            { "t.systemaudithardware.17", new[]{ "系统日志里有内核处理器降频记录 多为散热或供电不足 越玩越卡的常见真因 清灰改善风道或检查电源适配器后再看这项", "The system log contains kernel processor throttling records, usually thermal or power-delivery shortfalls — a common real cause of games getting choppier over time. Clean out dust, improve airflow, or check the power adapter, then recheck this item." } },
            { "t.systemaudithardware.18", new[]{ "系统日志无处理器降频记录 散热和供电目前没拖后腿", "No processor throttling records in the system log. Cooling and power delivery are not holding you back right now." } },
            { "t.systemaudithardware.19", new[]{ "灯效常驻软件", "Resident RGB lighting software" } },
            { "t.systemaudithardware.20", new[]{ "社区多有此类软件引发帧时间尖峰的成案 遇到无法归因的卡顿时 建议先退出它们对比一局再下结论", "The community has documented cases of such software causing frame-time spikes. When you hit stutter you cannot attribute, quit them first and compare a match before drawing conclusions." } },
            { "t.systemaudithardware.21", new[]{ "Ryzen 分支预测优化", "Ryzen branch prediction optimization" } },
            { "t.systemaudithardware.22", new[]{ "系统版本较旧", "Windows version is old" } },
            { "t.systemaudithardware.23", new[]{ "24H2 已含", "Included in 24H2" } },
            { "t.systemaudithardware.24", new[]{ "Windows 11 24H2 为 Ryzen 加入分支预测优化 台架实测游戏平均快一成 个别标题更多 23H2 装齐 2024 年 8 月之后的累积更新也已回移 建议更新系统", "Windows 11 24H2 adds branch prediction optimizations for Ryzen; bench-verified around 10% faster on average in games, more in some titles. 23H2 with the cumulative updates from after August 2024 also has it backported. Update Windows." } },
            { "t.systemaudithardware.25", new[]{ "当前系统已包含 AMD 分支预测优化 不用处理", "This Windows version already includes the AMD branch prediction optimizations. No action needed." } },
            { "t.systemaudithardware.26", new[]{ "旧 DX10 DX11 游戏的窗口化呈现已走升级路径 保持就行", "Windowed presentation of old DX10/DX11 games already uses the upgraded path. Keep it as is." } },
            { "t.systemaudithardware.27", new[]{ "微软官方背书的降延迟机制 旧 DX10 DX11 游戏窗口化时改走翻转模型 还解锁自动 HDR 与可变刷新率 做法 系统环境页拨开 窗口化游戏优化 开关 重启游戏后生效", "A latency-reduction mechanism officially backed by Microsoft: old DX10/DX11 games switch to the flip model when windowed, and it also unlocks Auto HDR and variable refresh rate. How: flip the Optimizations for Windowed Games switch on the System Environment page; takes effect after restarting the game." } },
            { "t.systemaudithardware.28", new[]{ "显卡 MSI 中断", "GPU MSI interrupts" } },
            { "t.systemaudithardware.29", new[]{ " 个设备被关闭", " device(s) disabled" } },
            { "t.systemaudithardware.30", new[]{ "正常", "Normal" } },
            { "t.systemaudithardware.31", new[]{ "MSISupported 被显式写成 0 可能是旧优化工具残留 也可能是为绕开这张卡开 MSI 后的黑屏死机而有意关闭 中断退回传统线模式会抬高 DPC 延迟 若这台机器没因 MSI 出过问题可点右侧修复写回 重启生效 可还原", "MSISupported was explicitly set to 0 — possibly residue from an old optimization tool, but possibly disabled on purpose to work around black screens or hangs this GPU had with MSI enabled. Legacy line-based interrupts raise DPC latency. If this machine never had MSI-related problems, click fix on the right to write it back; takes effect after reboot; restorable." } },
            { "t.systemaudithardware.32", new[]{ "消息信号中断未被干预 现代驱动默认即为 MSI 不用处理", "Message-signaled interrupts have not been tampered with; modern drivers default to MSI. No action needed." } },
