            { "t.systemaudit.37", new[]{ " 本机不划分后台核心", " background cores not partitioned on this machine" } },
            { "t.systemaudit.38", new[]{ "整机 CPU 占用", "Total CPU usage" } },
            { "t.systemaudit.39", new[]{ "体检窗口 ", "Checkup window " } },
            { "t.systemaudit.40", new[]{ " 秒", " s" } },
            { "t.systemaudit.41", new[]{ " 毫秒", " ms" } },
            { "t.systemaudit.42", new[]{ " 内的平均占用", " — average usage within this window" } },
            { "t.systemaudit.43", new[]{ "中断分布", "Interrupt distribution" } },
            { "t.systemaudit.44", new[]{ "线程 ", "Thread " } },
            { "t.systemaudit.45", new[]{ "被硬件中断占去 ", "time taken by hardware interrupts " } },
            { "t.systemaudit.46", new[]{ "本次窗口内中断主要来自 ", "Interrupts in this window came mainly from " } },
            { "t.systemaudit.47", new[]{ " 做法 这几个里 nvlddmkm 是显卡 dxgkrnl 是显示子系统 对应去系统环境页开 GPU USB 两个避让开关 重启后再测 stornvme storport 是硬盘 网卡类走 ndis tcpip 这两类的中断路由在驱动层 本软件不碰", " — How: among these, nvlddmkm is the GPU and dxgkrnl is the display subsystem — enable the GPU and USB avoidance switches on the System Environment page and re-test after reboot. stornvme/storport are storage; network goes through ndis/tcpip. Interrupt routing for those two classes lives in the driver layer, and this app does not touch it." } },
            { "t.systemaudit.48", new[]{ " 当前量级不影响帧 列出来只作参考", " Current magnitude does not affect frames; listed for reference only." } },
            { "t.systemaudit.49", new[]{ "到了能影响帧的量级 做法 去系统环境页把 GPU 中断亲和优化开关打开 重启后回这里再测对比", "At a magnitude that can affect frames. How: on the System Environment page, turn on the GPU interrupt affinity optimization switch, reboot, then come back here and re-test to compare." } },
            { "t.systemaudit.50", new[]{ "短窗口只能看出量级 分辨率约 0.5% 要精确值请用 30 秒测量", "A short window only shows the order of magnitude (resolution about 0.5%). For a precise value use the 30-second measurement." } },
            { "t.systemaudit.51", new[]{ "长窗口测量 分辨率约 0.05%", "Long-window measurement, resolution about 0.05%" } },
            { "t.systemaudit.52", new[]{ "测量失败", "Measurement failed" } },
            { "t.systemaudit.53", new[]{ "处理器性能接口不可用", "Processor performance interface unavailable" } },
